<script>
import { reactive, onMounted, onUnmounted, nextTick, inject } from 'vue'
import { useRouter } from 'vue-router'

export default {
  name: 'IndexPage',
  setup() {
    // 从 App.vue 注入全局 Toast
    const showToast = inject('showToast', () => {})
    const router = useRouter()

    // ===== 能力图鉴数据 =====
    const skills = reactive([
      { icon: '🐛', name: '写Bug', width: 98, animated: false },
      { icon: '🔧', name: '修Bug', width: 30, animated: false },
      { icon: '🔍', name: '找Bug', width: 5, animated: false },
      { icon: '📋', name: 'Ctrl+C / Ctrl+V', width: 99, animated: false },
      { icon: '🎣', name: '摸鱼', width: 100, animated: false },
      { icon: '🤖', name: '调教AI', width: 95, animated: false }
    ])

    const skillTags = [
      'Vue.js', 'JavaScript', 'HTML & CSS', 'Python',
      'Node.js', 'Git & GitHub', 'C++', 'SQL', 'GDScript',
      'Blender', 'KubeJS',
    ]

    // ===== 兴趣爱好数据 =====
    const hobbies = [
      { icon: '💻', name: '写代码', desc: '80%摸鱼+20%代码' },
      { icon: '🎮', name: '打游戏', desc: '认真摸鱼时间' },
      { icon: '🎧', name: '听音乐', desc: '假装在听其实发呆' },
      { icon: '🛸', name: '调试虫洞', desc: '和Bug斗智斗勇' },
      { icon: '🧪', name: '折腾新技术', desc: '锟斤拷烫烫烫' },
      { icon: '☕', name: '喝咖啡', desc: '生命体征维持液' }
    ]

    // ===== 头像彩蛋 =====
    const emojis = ['BQ', '🧑‍💻', '🤖', '☕', '✨', '🛸', '🎯', '🧙‍♂️']
    let clickCount = 0

    function handleAvatarClick(event) {
      clickCount++
      const avatar = event.target
      avatar.textContent = emojis[clickCount % emojis.length]
      avatar.style.transform = 'scale(1.15)'
      setTimeout(() => {
        avatar.style.transform = 'scale(1)'
      }, 200)

      const funMessages = [
        '点击了！并没有什么发生 😄',
        '你还真点啊？(￣▽￣)',
        '再点一次试试？',
        '好吧你赢了 🏆',
        '够啦！(╯°□°)╯ ︵ ┻━┻',
        '给你闲的 (*￣︿￣)'
      ]

      if (clickCount <= 6) {
        showToast(funMessages[clickCount - 1])
      } else if (clickCount === 7) {
        showToast('🎉 恭喜你发现了头像彩蛋！')
      } else {
        showToast('还在点？试试点打招呼按钮吧 👆')
      }
    }

    // ===== 滚动渐入动画 =====
    let fadeObserver = null
    let skillObserver = null

    onMounted(() => {
      // 时间问候
      const hour = new Date().getHours()
      let timeGreet
      if (hour < 6) timeGreet = '凌晨了还在写代码？早点休息 🌙'
      else if (hour < 9) timeGreet = '早上好！新的一天从写Bug开始 ☀️'
      else if (hour < 12) timeGreet = '上午好！摸鱼的好时光 🎣'
      else if (hour < 14) timeGreet = '中午好！该续杯咖啡了 ☕'
      else if (hour < 18) timeGreet = '下午好！Bug修完了吗？🐛'
      else if (hour < 22) timeGreet = '晚上好！高效时段到了 💻'
      else timeGreet = '夜深了，和Bug搏斗中… 🦉'

      setTimeout(() => {
        showToast(timeGreet)
      }, 300)

      // 渐入动画 Observer
      fadeObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('visible')
          }
        })
      }, {
        threshold: 0.15,
        rootMargin: '0px 0px -30px 0px'
      })

      const fadeElements = document.querySelectorAll('.homepage .fade-in')
      fadeElements.forEach(el => fadeObserver.observe(el))

      // 技能条动画 Observer
      skillObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            const bar = entry.target
            const targetWidth = bar.getAttribute('data-width')
            bar.style.width = targetWidth + '%'
            skillObserver.unobserve(bar)
          }
        })
      }, { threshold: 0.3 })

      nextTick(() => {
        const skillBars = document.querySelectorAll('.homepage .skill-bar-fill')
        skillBars.forEach(bar => {
          bar.style.width = '0%'
          skillObserver.observe(bar)
        })
      })
    })

    onUnmounted(() => {
      if (fadeObserver) fadeObserver.disconnect()
      if (skillObserver) skillObserver.disconnect()
    })

    // ===== 返回 Coming Soon =====
    const goToComingSoon = () => {
      router.push('/')
    }

    return {
      skills,
      skillTags,
      hobbies,
      handleAvatarClick,
      goToComingSoon
    }
  }
}
</script>

